238	    } | [Behavior](reference.md#${contract}) |\n`;
239	  }
240	  text += '\n## Declarations\n\n';
241	  for (const name of names) {
242	    const bindings = byName.get(name);
243	    const locations = [...new Set(bindings.flatMap((b) => b.declarations))];
244	    const found = locations
245	      .map((location) => declarations.get(location))
246	      .filter(Boolean);
247	    const namespace = routes.find(([, value]) =>
248	      locations.some(
249	        (location) =>
250	          declarationPath(location) === declarationPath(value.require.types),
251	      ),
252	    );
253	    assert(found.length || namespace, `Public declaration missing for ${name}`);
