258	    text += `<a id="${anchor(name)}"></a>\n\n### ${name}\n\n`;
259	    text += `${
260	      bindings.some((b) => b.runtime)
261	        ? 'Runtime value and public type surface.'
262	        : 'Type-only; no runtime constructor/value.'
263	    } [Owning contract](reference.md#${contract}) · [${
264	      example.startsWith('examples/')
265	        ? 'Runnable example'
266	        : 'Executable snippet'
267	    }](${exampleLink})\n\n`;
268	    text +=
269	      'Supported imports: ' +
270	      [...new Set(bindings.map((b) => specifier(b.entry)))]
271	        .sort()
272	        .map((s) => `\`${s}\``)
273	        .join(', ') +
274	      '.\n\n';
275	    if (namespace && !found.length) {
276	      const members = [
277	        ...new Set(
278	          census.bindings
279	            .filter((b) => b.entry === namespace[0])
280	            .map((b) => b.name),
281	        ),
282	      ].sort();
283	      text +=
284	        `Namespace for \`${specifier(namespace[0])}\`: ` +
285	        members.map((member) => `[${member}](#${anchor(member)})`).join(', ') +
286	        '.\n\n';
287	      continue;
288	    }
289	    text +=
290	      '```ts\n' +
291	      [...new Set(found.map((d) => displayType(d.signature)))].join('\n') +
292	      '\n```\n\n';
293	    const members = new Map();
294	    for (const declaration of found) {
295	      for (const member of declaration.members || [])
296	        members.set(member.name, member.type);
297	    }
298	    if (members.size) {
299	      text +=
300	        '<details>\n<summary>Resolved public members (including inherited/mapped fields)</summary>\n\n| Member | Type |\n| --- | --- |\n';
301	      for (const [member, type] of [...members].sort(([a], [b]) =>
302	        a < b ? -1 : a > b ? 1 : 0,
303	      ))
304	        text += `| \`${member}\` | <code>${cell(type)}</code> |\n`;
305	      text += '\n</details>\n\n';
306	    }
307	  }
308	  return text;
309	}
310	function saveIndex(filename, markdown, check) {
311	  if (check) {
312	    assert(
313	      fs.existsSync(filename) && fs.readFileSync(filename, 'utf8') === markdown,
314	      'Public API index is stale; run npm run docs:api',
315	    );
316	  } else fs.writeFileSync(filename, markdown);
317	}
318	if (require.main === module) {
319	  assert(
320	    process.argv.slice(2).every((arg) => arg === '--check'),
321	    'Usage: node scripts/build-api-index.cjs [--check]',
322	  );
323	  const root = path.resolve(__dirname, '..');
324	  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'ctt-api-index-'));
325	  try {
326	    execFileSync(
327	      process.execPath,
328	      [path.join(__dirname, 'api-clarity-census.cjs'), temporary],
329	      { cwd: root, stdio: 'pipe' },
330	    );
331	    const census = JSON.parse(
332	      fs.readFileSync(path.join(temporary, 'public-api-census.json'), 'utf8'),
333	    );
334	    saveIndex(
335	      path.join(root, 'docs/api-index.md'),
336	      renderApiIndex(census),
337	      process.argv.includes('--check'),
338	    );
339	    console.log(
340	      `Public API index ${
341	        process.argv.includes('--check') ? 'verified' : 'generated'
342	      }: ${new Set(census.bindings.map((b) => b.name)).size} symbols, ${
343	        census.bindings.length
344	      } bindings.`,
345	    );
346	  } finally {
347	    fs.rmSync(temporary, { recursive: true, force: true });
348	  }
349	}
350	module.exports = { renderApiIndex, saveIndex };
