  ],
  VisitorPhaseSelection: [
    'options-and-defaults',
    'examples/event-delivery-selection-example.ts',
  ],
  EffectiveTraversalExecutionOptions: [
    'inspection-and-execution',
    'examples/event-delivery-selection-example.ts',
  ],
