1	import { preparationIssue } from './lib/preparationIssue';
2	import type { ResolvedGraphsContainer } from '@core/graph/ResolvedGraphsContainer';
3	import type {
4	  AsyncDagDiscoverySource,
5	  DagDiscoverySource,
6	} from '@core/TraversableGraph';
7	import type { VertexTypes } from '@core/TreeTypeParameters';
8	import { AsyncDagTraversal } from './AsyncDagTraversal';
9	import { capturePreparedSource } from './lib/capturePreparedSource';
10	import type { PrepareDagResult } from './lib/DagDefinition';
11	import { dagRunnerCapabilities } from './lib/dagRunnerCapabilities';
12	import { assertPreparedOptions, makePreparedDag } from './lib/makePreparedDag';
13	import { prepareDagSource } from './lib/prepareDagSource';
14	
15	export type PrepareDagOptions = {
16	  syntheticRoot?: boolean;
17	  rootWorkDependencies?: 'honor' | 'ignore';
18	  dependsOnWorkDefault?: 'none' | 'discoveryParentWork';
19	  traversableTree?: never;
20	  visitors?: never;
21	  completedWork?: never;
22	  traversalRunnerInternalObjects?: never;
23	  workCompletion?: never;
24	  discovery?: never;
25	  transformChildHints?: never;
26	  retainOriginalGraphStructure?: never;
27	};
28	export type PrepareDagInput<
29	  T extends VertexTypes,
30	  ID = unknown,
31	> = PrepareDagOptions & {
32	  traversableGraph: DagDiscoverySource<T, T, ID>;
33	};
34	export type PrepareAsyncDagInput<
35	  T extends VertexTypes,
36	  ID = unknown,
37	> = PrepareDagOptions & {
38	  traversableGraph: AsyncDagDiscoverySource<T, T, ID>;
39	  concurrency?: number;
40	};
41	
42	const preparationFields = [
43	  'traversableGraph',
44	  'syntheticRoot',
45	  'rootWorkDependencies',
46	  'dependsOnWorkDefault',
47	];
48	
49	/** Discover and validate without visitors; caller source errors retain exact identity. */
50	export function prepareDag<T extends VertexTypes, ID = unknown>(
51	  input: PrepareDagInput<T, ID>,
52	): PrepareDagResult<T['VertexData'], ID> {
53	  return prepareDagSource(input);
54	}
55	
56	/** Async discovery produces the same reusable in-memory definition. */
57	export function prepareDagAsync<T extends VertexTypes, ID = unknown>(
58	  input: PrepareDagInput<T, ID> & { concurrency?: number },
59	): Promise<PrepareDagResult<T['VertexData'], ID>>;
60	export function prepareDagAsync<T extends VertexTypes, ID = unknown>(
61	  input: PrepareAsyncDagInput<T, ID>,
62	): Promise<PrepareDagResult<T['VertexData'], ID>>;
63	export async function prepareDagAsync<T extends VertexTypes, ID = unknown>(
64	  input: PrepareAsyncDagInput<T, ID>,
65	): Promise<PrepareDagResult<T['VertexData'], ID>> {
66	  assertPreparedOptions(input, [...preparationFields, 'concurrency']);
67	  const captured = capturePreparedSource<T, ID>(input.traversableGraph, true);
68	  const runner = new AsyncDagTraversal<T, T, ID>({
69	    ...input,
70	    traversableGraph: captured.adapter,
71	  }).createRunner();
72	  try {
73	    await runner.prepare();
74	  } catch (error) {
75	    const issue = preparationIssue<ID>(
76	      dagRunnerCapabilities.get(runner)!.container.store,
77	      error,
78	    );
79	    if (issue === undefined) throw error;
80	    return { kind: 'invalid', issues: [issue] };
81	  }
82	  return {
83	    kind: 'valid',
84	    dag: makePreparedDag(
85	      dagRunnerCapabilities.get(runner)!
86	        .container as unknown as ResolvedGraphsContainer<T, T, ID>,
87	      captured.candidates,
88	      input.rootWorkDependencies ?? 'honor',
89	    ),
90	  };
91	}
